        ...$('Loop Over Items1').item.json,
        authCookie: readerToken
    }
}];

const currentItem = $('Code in JavaScript5').item.json;
const bookFullId = currentItem.bookId;
const totalPages = currentItem.totalPages;

if (!bookFullId || typeof bookFullId !== 'string') {
  throw new Error(`╨Э╨╡╨║╨╛╤А╤А╨╡╨║╤В╨╜╤Л╨╣ ID ╨║╨╜╨╕╨│╨╕: ${bookFullId}`);
}

const parts = bookFullId.includes('_') ? bookFullId.split('_') : [bookFullId, "0"];
const prefix = parts[0];
let numStr = parts[1] || "0"; 
const numPart = numStr.toString().padStart(9, '0');

const p1 = numPart.substring(0, 3);
const p2 = numPart.substring(3, 6);
const p3 = numPart.substring(6, 9);
const safeBookId = bookFullId.trim().replace(/[^\w.-]+/g, "_");

let urlList = "";
for (let i = 1; i <= Number(totalPages); i++) {
  const pagePad = i.toString().padStart(5, '0');
  urlList += `https://cdn.libfl.ru/books/${prefix}/${p1}/${p2}/${p3}/JPEG_HQ/${pagePad}.jpg\n`;
}

return [{
  json: {
    ...currentItem,
    bookId: bookFullId,
    safeBookId, 
    urlList,
    urlCount: Number(totalPages),
  }
}];

// ╨С╨╡╤А╨╡╨╝ ╨║╤Г╨║╨╕ ╤В╨╡╨║╤Г╤Й╨╡╨│╨╛ ╤Ж╨╕╨║╨╗╨░
const token = $('Code in JavaScript1').item.json.authCookie.split('=')[1];
const cookieContent = `.libfl.ru\tTRUE\t/\tFALSE\t2147483647\tReaderToken\t${token}`;
return [{ json: { cookieContent } }];

const rawData = items[0].json;

// ╨Я╨╛╨╗╤Г╤З╨░╨╡╨╝ ╤В╨╡╨║╤Б╤В ╤Б╤В╤А╨░╨╜╨╕╤Ж╤Л (╨╕╨╖ SSH stdout ╨╕╨╗╨╕ HTTP data)
let textContent = rawData.stdout || rawData.data || "";
if (typeof textContent !== 'string') {
    textContent = JSON.stringify(textContent);
}

let bookId = "Unknown";
let title = "Scan";
let author = "Unknown Author";
let totalPages = 600;

// ╨Ш╨й╨Х╨Ь ╨Ф╨Р╨Э╨Э╨л╨Х ╨Т HTML ╨Я╨а╨Ю╨б╨Ь╨Ю╨в╨а╨й╨Ш╨Ъ╨Р (Viewer)
// ╨Ш╤Й╨╡╨╝ ╨▒╨╗╨╛╨║ var bookInfo = { ... };
const bookInfoMatch = textContent.match(/var bookInfo\s*=\s*({[\s\S]*?});/);

if (bookInfoMatch) {
    try {
        const info = JSON.parse(bookInfoMatch[1]);
        if (info.ID) bookId = info.ID;
        if (info.Title) title = info.Title.trim();
        if (info.Author) author = info.Author;
    } catch (e) {
        console.log("╨Ю╤И╨╕╨▒╨║╨░ ╨┐╨░╤А╤Б╨╕╨╜╨│╨░ bookInfo JSON");
    }

    // ╨Ш╤Й╨╡╨╝ ╤В╨╛╤З╨╜╨╛╨╡ ╨║╨╛╨╗╨╕╤З╨╡╤Б╤В╨▓╨╛ ╤Б╤В╤А╨░╨╜╨╕╤Ж (CountJPG)
    const countMatch = textContent.match(/"CountJPG"\s*:\s*(\d+)/);
    if (countMatch) {
        totalPages = parseInt(countMatch[1]);
    }

    if (bookId === "Unknown") {
        throw new Error("╨Э╨╡ ╤Г╨┤╨░╨╗╨╛╤Б╤М ╨╜╨░╨╣╤В╨╕ ID ╨║╨╜╨╕╨│╨╕ ╨▓ ╨║╨╛╨┤╨╡ ╤Б╤В╤А╨░╨╜╨╕╤Ж╤Л Viewer'╨░!");
    }

    return [{
        json: {
            bookId: bookId,
            title: title,
            author: author,
            totalPages: totalPages
        }
    }];
}

throw new Error("╨Э╨╡ ╤Г╨┤╨░╨╗╨╛╤Б╤М ╨╜╨░╨╣╤В╨╕ ╨┐╨╡╤А╨╡╨╝╨╡╨╜╨╜╤Л╨╡ Viewer ╨╜╨░ ╤Б╤В╤А╨░╨╜╨╕╤Ж╨╡. ╨Т╨╛╨╖╨╝╨╛╨╢╨╜╨╛, ╨╖╨░╤Й╨╕╤В╨░ ╨╜╨╡ ╨┐╤А╨╛╨╣╨┤╨╡╨╜╨░ ╨╕╨╗╨╕ ╤В╨╛╨║╨╡╨╜ ╤Г╤Б╤В╨░╤А╨╡╨╗.");

const returnData = [];

// ╨Т╤Б╨┐╨╛╨╝╨╛╨│╨░╤В╨╡╨╗╤М╨╜╨░╤П ╤Д╤Г╨╜╨║╤Ж╨╕╤П ╨┤╨╗╤П ╨╛╤З╨╕╤Б╤В╨║╨╕ HTML-╤В╨╡╨│╨╛╨▓
const stripTags = (str) => {
  if (!str) return null;
  return str.replace(/<[^>]*>?/gm, '').trim();
};

// ╨Т╤Б╨┐╨╛╨╝╨╛╨│╨░╤В╨╡╨╗╤М╨╜╨░╤П ╤Д╤Г╨╜╨║╤Ж╨╕╤П ╨┤╨╗╤П ╨┐╨╛╨╕╤Б╨║╨░ ╨╖╨╜╨░╤З╨╡╨╜╨╕╤П ╨┐╨╛ ╨┐╤А╨╛╤Б╤В╨╛╨╝╤Г ╨┐╨░╤В╤В╨╡╤А╨╜╤Г
const findMatch = (html, regex, index = 1) => {
  const match = html.match(regex);
  return match ? stripTags(match[index]) : null;
};

for (const item of items) {
  const html = item.json.stdout;
  if (!html) continue;

  // 1. ╨Ю╤Б╨╜╨╛╨▓╨╜╤Л╨╡ ╨╝╨╡╤В╨░╨┤╨░╨╜╨╜╤Л╨╡ ╤З╨╡╤А╨╡╨╖ Regex
  const title = findMatch(html, /<h3 property="name">([\s\S]*?)<\/h3>/);
  const mainAuthor = findMatch(html, /<span class='author'>([\s\S]*?)<\/span>/);
  const recordId = findMatch(html, /value="([^"]+)" class="hiddenId"/);

  // 2. ╨Я╨░╤А╤Б╨╕╨╜╨│ ╨╛╤Б╨╜╨╛╨▓╨╜╨╛╨╣ ╤В╨░╨▒╨╗╨╕╤Ж╤Л (╨С╨╕╨▒╨╗╨╕╨╛╨│╤А╨░╤Д╨╕╤З╨╡╤Б╨║╨╕╨╡ ╨┐╨╛╨┤╤А╨╛╨▒╨╜╨╛╤Б╤В╨╕)
  const details = {};
  // ╨Ш╤Й╨╡╨╝ ╨▓╤Б╨╡ ╨▓╤Е╨╛╨╢╨┤╨╡╨╜╨╕╤П <th>Key</th><td>Value</td>
  const tableRegex = /<th>(.*?)<\/th><td>(.*?)<\/td>/g;
  let match;
  while ((match = tableRegex.exec(html)) !== null) {
    const key = stripTags(match[1]);
    const val = stripTags(match[2]);
    details[key] = val;
  }

  // ╨б╨╛╨▒╨╕╤А╨░╨╡╨╝ ╨░╨▓╤В╨╛╤А╨╛╨▓
  const authors = [mainAuthor];
  if (details['╨Ф╤А╤Г╨│╨╛╨╣ ╨░╨▓╤В╨╛╤А']) {
    authors.push(details['╨Ф╤А╤Г╨│╨╛╨╣ ╨░╨▓╤В╨╛╤А']);
  }

  // 3. ╨Ю╨▒╨╗╨╛╨╢╨║╨░
  let coverUrl = null;
  const coverMatch = html.match(/data-fancybox='covers' href='([^']+)'/);
  if (coverMatch) {
    coverUrl = coverMatch[1];
    if (coverUrl && !coverUrl.startsWith('http')) {
      coverUrl = `https://catalog.libfl.ru${coverUrl}`;
    }
  }

  // 4. ╨Я╨░╤А╤Б╨╕╨╜╨│ ╤Н╨║╨╖╨╡╨╝╨┐╨╗╤П╤А╨╛╨▓ (Exemplars)
  // ╨а╨░╨╖╨▒╨╕╨▓╨░╨╡╨╝ HTML ╨╜╨░ ╨║╤Г╤Б╨║╨╕ ╨┐╨╛ ╨║╨╗╨░╤Б╤Б╤Г exemplar
  const holdings = [];
  const exemplarParts = html.split('class=exemplar>');

  // ╨Я╤А╨╛╨┐╤Г╤Б╨║╨░╨╡╨╝ ╨╜╤Г╨╗╨╡╨▓╨╛╨╣ ╤Н╨╗╨╡╨╝╨╡╨╜╤В (╤Н╤В╨╛ ╨▓╤Б╨╡ ╤З╤В╨╛ ╨Ф╨Ю ╨┐╨╡╤А╨▓╨╛╨│╨╛ ╤Н╨║╨╖╨╡╨╝╨┐╨╗╤П╤А╨░)
  for (let i = 1; i < exemplarParts.length; i++) {
    const part = exemplarParts[i];

    // ╨Э╨╛╨╝╨╡╤А ╨║╨╛╨┐╨╕╨╕
    const copyNumMatch = part.match(/<h3[^>]*>#&nbsp;(\d+)<\/h3>/);
    const copyNum = copyNumMatch ? copyNumMatch[1] : null;

    // ╨Ф╨░╨╜╨╜╤Л╨╡ ╨▓╨╜╤Г╤В╤А╨╕ ╤Н╨║╨╖╨╡╨╝╨┐╨╗╤П╤А╨░ (╤Б╨╜╨╛╨▓╨░ ╤В╨░╨▒╨╗╨╕╤Ж╨░)
    const exData = {};
    let exMatch;
    // ╨б╨╛╨╖╨┤╨░╨╡╨╝ ╨╜╨╛╨▓╤Л╨╣ regex ╨╛╨▒╤К╨╡╨║╤В ╨┤╨╗╤П ╤Ж╨╕╨║╨╗╨░, ╤З╤В╨╛╨▒╤Л ╨╜╨╡ ╨║╨╛╨╜╤Д╨╗╨╕╨║╤В╨╛╨▓╨░╤В╤М ╤Б ╨▓╨╜╨╡╤И╨╜╨╕╨╝
    const exTableRegex = /<th>(.*?)<\/th><td>(.*?)<\/td>/g;

    // ╨Ю╨│╤А╨░╨╜╨╕╤З╨╕╨╝ ╨┐╨╛╨╕╤Б╨║ ╤В╨╡╨║╤Г╤Й╨╕╨╝ ╨▒╨╗╨╛╨║╨╛╨╝ (╨┤╨╛ ╤Б╨╗╨╡╨┤╤Г╤О╤Й╨╡╨│╨╛ div)
    const tableBlock = part.split('</table>')[0]; 

    while ((exMatch = exTableRegex.exec(tableBlock)) !== null) {
      exData[stripTags(exMatch[1])] = stripTags(exMatch[2]);
    }

    if (copyNum || exData['╨Э╨╛╤Б╨╕╤В╨╡╨╗╤М']) {
       holdings.push({
        copy_number: copyNum,
        format: exData['╨Э╨╛╤Б╨╕╤В╨╡╨╗╤М'] || null,
        status: exData['╨Ъ╨╗╨░╤Б╤Б ╨╕╨╖╨┤╨░╨╜╨╕╤П'] || '╨Э╨╡ ╤Г╨║╨░╨╖╨░╨╜',
        location: exData['╨Ь╨╡╤Б╤В╨╛╨╜╨░╤Е╨╛╨╢╨┤╨╡╨╜╨╕╨╡'] || null,
        call_number: exData['╨и╨╕╤Д╤А'] || null,
        inv_number: exData['╨Ш╨╜╨▓. ╨╜╨╛╨╝╨╡╤А'] || null
      });
    }
  }

  returnData.push({
    json: {
      id: recordId,
      title: title,
      authors: authors.filter(Boolean),
      publisher: details['╨Ш╨╖╨┤╨░╤В╨╡╨╗╤М╤Б╤В╨▓╨╛'] || null,
      publish_year: details['╨Ф╨░╤В╨░ ╨╕╨╖╨┤╨░╨╜╨╕╤П'] ? parseInt(details['╨Ф╨░╤В╨░ ╨╕╨╖╨┤╨░╨╜╨╕╤П']) : null,
      publish_city: details['╨Ь╨╡╤Б╤В╨╛ ╨╕╨╖╨┤╨░╨╜╨╕╤П'] || null,
      language: details['╨п╨╖╤Л╨║'] || null,
      topics: [details['╨в╨╡╨╝╨░╤В╨╕╨║╨░'], details['╨Я╤А╨╡╨┤╨╝╨╡╤В╨╜╨░╤П ╤А╤Г╨▒╤А╨╕╨║╨░']].filter(Boolean),
      cover_image: coverUrl,
      holdings: holdings,
      source_url: `https://catalog.libfl.ru/Record/${recordId}`
    }
  });
}

return returnData;

// ╨Э╨░╨┤╨╡╨╢╨╜╨░╤П ╤Д╤Г╨╜╨║╤Ж╨╕╤П ╨┤╨╗╤П ╨┐╨╛╨╗╤Г╤З╨╡╨╜╨╕╤П ╨┤╨░╨╜╨╜╤Л╤Е ╤В╨╡╨║╤Г╤Й╨╡╨╣ ╨║╨╜╨╕╨│╨╕ ╨▓ ╤Ж╨╕╨║╨╗╨╡
function safeGetItem(nodeName) {
  try {
    return $(nodeName).item.json;
  } catch (e) {
    try {
      return $(nodeName).first().json;
    } catch (err) {
      return {};
    }
  }
}

// ╨Ч╨░╨▒╨╕╤А╨░╨╡╨╝ ╨┤╨░╨╜╨╜╤Л╨╡ ╨╕╨╖ ╨┤╤А╤Г╨│╨╕╤Е ╨╜╨╛╨┤
const cat = safeGetItem('metadate2');            
const vw  = safeGetItem('Code in JavaScript5');  
const loopItem = safeGetItem('Loop Over Items1');  
const js2 = safeGetItem('Code in JavaScript2');

// 1. ╨Ш╨Ф╨Х╨Р╨Ы╨м╨Э╨л╨Щ ╨Я╨г╨в╨м ╨С╨Х╨Ч ╨Я╨Р╨а╨б╨Ш╨Э╨У╨Р ╨Ы╨Ю╨У╨Ю╨Т
// ╨С╨╡╤А╨╡╨╝ ID ╨║╨╜╨╕╨│╨╕ (╨╜╨░╨┐╤А╨╕╨╝╨╡╤А, BJVVV_1465084) ╨╕ ╨┐╤А╨╛╤Б╤В╨╛ ╨┐╨╛╨┤╤Б╤В╨░╨▓╨╗╤П╨╡╨╝ ╨▓ ╤Д╨╛╤А╨╝╤Г╨╗╤Г ╨┐╤Г╤В╨╕
const safeId = js2.safeBookId || loopItem.safeBookId || "UNKNOWN_ID";
const fullPath = `/data/bookbuilder/books/${safeId}/${safeId}.pdf`;

// 2. ╨б╨▒╨╛╤А ╨╛╤Б╤В╨░╨╗╤М╨╜╤Л╤Е ╨╝╨╡╤В╨░╨┤╨░╨╜╨╜╤Л╤Е
const title = (cat.title || vw.title || loopItem.title || 'Scan').toString().trim();
const authorsArr = (cat.authors && cat.authors.length ? cat.authors : [vw.author, loopItem.author])
    .filter(Boolean).map(a => a.toString().trim());

const publisher = (cat.publisher || '').toString().trim();
const year = cat.publish_year ? String(cat.publish_year) : (cat.year ? String(cat.year) : '');
const language = (cat.language || '').toString().trim();
const topics = (cat.topics || []).map(t => t.toString().trim()).filter(Boolean);

const subjectParts = [
  publisher && `╨Ш╨╖╨┤╨░╤В╨╡╨╗╤М: ${publisher}`,
  year && `╨У╨╛╨┤: ${year}`,
  language && `╨п╨╖╤Л╨║: ${language}`,
].filter(Boolean);

const keywords = [...topics, language, publisher, year].filter(Boolean).join(', ');

return [{
  json: {
    full_path: fullPath,
    pdf_title: title,
    pdf_author: authorsArr.join('; ') || 'Unknown Author',
    pdf_subject: subjectParts.join(' | ') || 'Scan',
    pdf_keywords: keywords,
    pdf_publisher: publisher,
    pdf_language: language,
    pdf_year: year,
  }
}];

// ╨Я╨╛╨╗╤Г╤З╨░╨╡╨╝ ╨╖╨░╨│╨╛╨╗╨╛╨▓╨║╨╕ ╨╛╤В ╨┐╤А╨╡╨┤╤Л╨┤╤Г╤Й╨╡╨│╨╛ ╤И╨░╨│╨░
const headers = items[0].json.headers;
const setCookie = headers['set-cookie'];

// ╨б╨╛╨▒╨╕╤А╨░╨╡╨╝ ╨║╤Г╨║╨╕ ╨▓ ╤Б╤В╤А╨╛╨║╤Г
let cookieString = "";
if (Array.isArray(setCookie)) {
    // ╨Х╤Б╨╗╨╕ ╨┐╤А╨╕╤И╨╗╨╛ ╨╜╨╡╤Б╨║╨╛╨╗╤М╨║╨╛ ╨║╤Г╨║ (╨╝╨░╤Б╤Б╨╕╨▓)
    cookieString = setCookie.map(c => c.split(';')[0]).join('; ');
} else if (typeof setCookie === 'string') {
    // ╨Х╤Б╨╗╨╕ ╨┐╤А╨╕╤И╨╗╨░ ╨╛╨┤╨╜╨░ ╨║╤Г╨║╨░
    cookieString = setCookie.split(';')[0];
}

// ╨Т╨╛╨╖╨▓╤А╨░╤Й╨░╨╡╨╝ ╤Б╤В╤А╨╛╨║╤Г, ╨║╨╛╤В╨╛╤А╤Г╤О ╨▓╤Б╤В╨░╨▓╨╕╨╝ ╨▓ ╤Б╨╗╨╡╨┤╤Г╤О╤Й╨╕╨╣ ╨╖╨░╨┐╤А╨╛╤Б
return [{
    json: {
        cookieString: cookieString
    }
}];

let meta = {};
try {
    meta = $('Build PDF Metadata').item.json; // <-- ╨Ч╨░╨╝╨╡╨╜╨╕╨╗╨╕ first ╨╜╨░ item
} catch (e) {
    console.log("Meta not found");
}

// 2. ╨д╤Г╨╜╨║╤Ж╨╕╤П ╨╛╤З╨╕╤Б╤В╨║╨╕
const clean = (str) => {
    if (!str) return "";
    return str.toString().replace(/[\/\\:*?"<>|]/g, '').replace(/\s+/g, ' ').trim();
};

// 3. ╨д╨╛╤А╨╝╨╕╤А╤Г╨╡╨╝ ╨╕╨╝╤П
const title = clean(meta.pdf_title) || "Scan";
const author = clean(meta.pdf_author) || "NoAuthor";
const year = clean(meta.pdf_year) || "";

let newName = `${author} - ${title}`;
if (year) {
    newName += ` - ${year}`;
}
newName += ".pdf";

// 4. ╨Я╤А╨╕╤Б╨▓╨░╨╕╨▓╨░╨╡╨╝ ╨╕╨╝╤П
for (const item of items) {
    // ╨Р) ╨Я╤А╨╕╤Б╨▓╨░╨╕╨▓╨░╨╡╨╝ ╨▒╨╕╨╜╨░╤А╨╜╨╕╨║╤Г (╨┤╨╗╤П ╨▓╨╕╨┤╨░)
    if (item.binary && item.binary.data) {
        item.binary.data.fileName = newName;
    }

    // ╨С) ╨Т╨Р╨Ц╨Э╨Ю: ╨Я╤А╨╕╤Б╨▓╨░╨╕╨▓╨░╨╡╨╝ ╨▓ JSON, ╤З╤В╨╛╨▒╤Л ╨╕╤Б╨┐╨╛╨╗╤М╨╖╨╛╨▓╨░╤В╤М ╨▓ ╤Б╨╗╨╡╨┤╤Г╤О╤Й╨╡╨╣ ╨╜╨╛╨┤╨╡
    item.json.finalFileName = newName;
}

